contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint8 msg) public {
        require(msg == 1, "unreachable");

        uint32 rBefore = c._RState_(); if (__ESBMC_reverted()) return;
        uint256 qrBefore = uint256(c._QUOTE_RESERVE_());
        uint256 qtBefore = uint256(c._QUOTE_TARGET_());

        c.correctRState(); if (__ESBMC_reverted()) return;

        uint32 rAfter = c._RState_(); if (__ESBMC_reverted()) return;
        uint256 qrAfter = uint256(c._QUOTE_RESERVE_());
        uint256 qtAfter = uint256(c._QUOTE_TARGET_());

        uint32 ABOVE_ONE = 2;

        bool wasRectified = (rBefore == ABOVE_ONE && qrBefore < qtBefore);
        bool becameOne = (rAfter == 1);
        bool unchanged = (rAfter == rBefore);

        assert(wasRectified ? becameOne : unchanged);
    }

    receive() external payable {}
}

