pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint8 msg) internal {
        msg = 1;
        uint32 rBefore;
        try c._RState_() returns (uint32 __r) { rBefore = __r; } catch { return; }
        uint256 qrBefore = uint256(c._QUOTE_RESERVE_());
        uint256 qtBefore = uint256(c._QUOTE_TARGET_());
        try c.correctRState() {} catch { return; }
        uint32 rAfter;
        try c._RState_() returns (uint32 __r) { rAfter = __r; } catch { return; }
        uint256 qrAfter = uint256(c._QUOTE_RESERVE_());
        uint256 qtAfter = uint256(c._QUOTE_TARGET_());
        uint32 ABOVE_ONE = 2;
        bool wasRectified = (rBefore == ABOVE_ONE && qrBefore < qtBefore);
        bool becameOne = (rAfter == 1);
        bool unchanged = (rAfter == rBefore);
        assertTrue(wasRectified ? becameOne : unchanged);
    }

    function testFuzz_run(uint8 msg) public {
        _run(msg);
    }

    receive() external payable {}
}
